// TEST_MODE: 1 "hour" = 1 minute, 1 "day" = 1 minute, appointments last 2 minutes.
// Real timings. Set to true only for quick tests (and run the schedule every 2 minutes).
const TEST_MODE = false;
const HOUR = TEST_MODE ? 60 * 1000 : 60 * 60 * 1000;
const DAY = TEST_MODE ? 60 * 1000 : 24 * 60 * 60 * 1000;
const APPT_LENGTH = TEST_MODE ? 2 * 60 * 1000 : 30 * 60 * 1000;
const FOLLOWUP_AFTER = [1 * DAY, 3 * DAY, 7 * DAY];
const RECALL_DAYS = 180; // 6-month check-up reminder
const AFTERCARE = /fill|root|canal|extract|implant|surg|wisdom|whiten|crown|حشو|عصب|خلع|زراع|تبييض|جراح/i;

// Switches (Noor Settings): satisfaction_check, recall_reminders, missed_appointment, reminder_3d, first_visit_tips, aftercare_checkin, win_back.
const on = {};
try { $('Get Switches').all().forEach(function (i) { const r = i.json || {}; if (r.feature) on[String(r.feature).trim()] = String(r.enabled).trim().toUpperCase() === 'TRUE'; }); } catch (e) { /* off */ }
// Messages already sent (noor_sent_log), so nothing goes out twice.
const sent = {};
try { $('Get Sent Log').all().forEach(function (i) { const r = i.json || {}; if (r.phone && r.kind) sent[String(r.phone) + '|' + r.kind + '|' + String(r.ref || '')] = true; }); } catch (e) { /* none */ }
const was = function (p, k, ref) { return !!sent[String(p) + '|' + k + '|' + String(ref || '')]; };

const now = DateTime.now().setZone('Asia/Dubai');
const inDay = TEST_MODE || (now.hour >= 10 && now.hour < 19);
const out = [];

for (const item of $('Read Patients').all()) {
  const r = item.json;
  if (!r.phone) continue;
  if (/^000000000000/.test(String(r.phone))) continue; // test numbers never get messages
  const lang = String(r.language || '').toLowerCase().startsWith('ar') ? 'ar' : 'en';
  const firstName = String(r.name || '').trim().split(' ')[0] || (lang === 'ar' ? 'عزيزنا' : 'there');
  const service = String(r.service || (lang === 'ar' ? 'الأسنان' : 'dental'));
  const status = String(r.status || '').toLowerCase().trim();
  if (status === 'opted_out') continue; // the patient replied STOP
  const row = {
    phone: String(r.phone),
    status: r.status || '',
    followups_sent: Number(r.followups_sent || 0),
    reminder_24h_sent: r.reminder_24h_sent || '',
    reminder_2h_sent: r.reminder_2h_sent || '',
    review_requested: r.review_requested || ''
  };

  // 1) Appointment reminders, first-visit tips, review requests / satisfaction check
  if ((status === 'booked' || status === 'confirmed') && r.appointment_start) {
    const start = DateTime.fromFormat(String(r.appointment_start), 'yyyy-MM-dd HH:mm', { zone: 'Asia/Dubai' });
    if (start.isValid) {
      const msUntil = start.toMillis() - now.toMillis();
      // Flags store the appointment time they were sent for, so a new booking gets fresh reminders.
      const key = String(r.appointment_start);
      const local = start.reconfigure({ locale: lang, numberingSystem: 'latn' });
      const dateText = local.toFormat('cccc d LLLL');
      const timeText = lang === 'ar'
        ? start.toFormat('h:mm') + (start.hour < 12 ? ' صباحاً' : ' مساءً')
        : start.toFormat('h:mm a');
      const when = lang === 'ar' ? dateText + ' الساعة ' + timeText : dateText + ' at ' + timeText;

      if (msUntil > 0 && msUntil <= 2 * HOUR && row.reminder_2h_sent !== key) {
        out.push({ json: { ...row, reminder_2h_sent: key, reminder_24h_sent: key, action: 'reminder', template: 'appointment_reminder|' + lang, p1: firstName, p2: service, p3: dateText, p4: timeText } });
        continue;
      }
      if (msUntil > 2 * HOUR && msUntil <= 24 * HOUR && row.reminder_24h_sent !== key) {
        out.push({ json: { ...row, reminder_24h_sent: key, action: 'reminder', template: 'appointment_reminder|' + lang, p1: firstName, p2: service, p3: dateText, p4: timeText } });
        continue;
      }
      // 2-4 days before: new patients get first-visit tips, returning patients the 3-day reminder (10:00-19:00, once)
      if (msUntil > 2 * DAY && msUntil <= 4 * DAY && inDay) {
        const isNew = /new|جديد/i.test(String(r.new_or_returning || ''));
        if (isNew && on.first_visit_tips && !was(row.phone, 'first_visit', key)) {
          out.push({ json: { ...row, action: 'tips', template: 'first_visit_tips|' + lang, p1: firstName, p2: when, log_kind: 'first_visit', log_ref: key } });
          continue;
        }
        if (!isNew && on.reminder_3d && !was(row.phone, 'reminder_3d', key)) {
          const dentist = String(r.dentist || (lang === 'ar' ? 'طبيبك' : 'your dentist'));
          out.push({ json: { ...row, action: 'reminder3d', template: 'appointment_reminder_3d|' + lang, p1: firstName, p2: service, p3: when, p4: dentist, log_kind: 'reminder_3d', log_ref: key } });
          continue;
        }
      }
      const reviewAt = start.toMillis() + APPT_LENGTH + HOUR;
      if (now.toMillis() >= reviewAt && row.review_requested !== key) {
        if (on.satisfaction_check) {
          const dentist = String(r.dentist || (lang === 'ar' ? 'طبيبك' : 'your dentist'));
          out.push({ json: { ...row, status: 'completed', review_requested: key, action: 'feedback', template: 'visit_feedback|' + lang, p1: firstName, p2: dentist } });
        } else {
          out.push({ json: { ...row, status: 'completed', review_requested: key, action: 'review', template: 'review_request|' + lang, p1: firstName } });
        }
        continue;
      }
    }
  }

  // 2) Follow-ups for leads who have not booked (8:00-20:00 Dubai time only)
  if (status === 'lead' && row.followups_sent < 3 && r.last_message_at) {
    const last = DateTime.fromFormat(String(r.last_message_at), 'yyyy-MM-dd HH:mm', { zone: 'Asia/Dubai' });
    const inHours = TEST_MODE || (now.hour >= 8 && now.hour < 20);
    if (last.isValid && inHours && now.toMillis() - last.toMillis() >= FOLLOWUP_AFTER[row.followups_sent]) {
      const sentCount = row.followups_sent + 1;
      out.push({ json: { ...row, followups_sent: sentCount, status: sentCount >= 3 ? 'no_reply' : 'lead', action: 'followup', template: 'booking_followup|' + lang, p1: firstName, p2: service } });
    }
    continue;
  }

  // 3) No-show: the team sets status to no_show in the Patients tab (10:00-19:00 only)
  if (status === 'no_show' && on.missed_appointment && inDay) {
    out.push({ json: { ...row, status: 'no_show_contacted', action: 'missed', template: 'missed_appointment|' + lang, p1: firstName, p2: service } });
    continue;
  }

  if (status === 'completed' && inDay && r.appointment_start) {
    const visit = DateTime.fromFormat(String(r.appointment_start), 'yyyy-MM-dd HH:mm', { zone: 'Asia/Dubai' });
    if (visit.isValid) {
      // 4) Aftercare check-in 20-48 hours after a treatment (not after a simple check-up or cleaning)
      const hrs = now.diff(visit, 'hours').hours;
      if (on.aftercare_checkin && AFTERCARE.test(service) && hrs >= 20 && hrs <= 48 && !was(row.phone, 'aftercare', r.appointment_start)) {
        out.push({ json: { ...row, action: 'aftercare', template: 'aftercare_checkin|' + lang, p1: firstName, p2: service, log_kind: 'aftercare', log_ref: String(r.appointment_start) } });
        continue;
      }
      // 5) 6-month recall after a completed visit (once)
      const days = now.diff(visit, 'days').days;
      if (on.recall_reminders && days >= RECALL_DAYS && days < RECALL_DAYS + 60) {
        out.push({ json: { ...row, status: 'recall_sent', action: 'recall', template: 'recall_reminder|' + lang, p1: firstName } });
        continue;
      }
    }
  }

  // 6) Win-back: leads who never answered the 3 follow-ups, 60-120 days later (once)
  if (status === 'no_reply' && on.win_back && inDay && r.last_message_at && !was(row.phone, 'win_back', '')) {
    const last = DateTime.fromFormat(String(r.last_message_at), 'yyyy-MM-dd HH:mm', { zone: 'Asia/Dubai' });
    const days = last.isValid ? now.diff(last, 'days').days : -1;
    if (days >= 60 && days < 120) {
      out.push({ json: { ...row, action: 'winback', template: 'win_back|' + lang, p1: firstName, log_kind: 'win_back', log_ref: '' } });
      continue;
    }
  }
}

// What Noor remembers about each automatic message, so she understands replies like "Confirm", "YES" or a day.
function hist(j) {
  switch (j.action) {
    case 'reminder': return '[Noor sent an automatic appointment reminder: ' + j.p2 + ' on ' + j.p3 + ' at ' + j.p4 + ', with Confirm and Reschedule buttons]';
    case 'reminder3d': return '[Noor sent an automatic reminder 3 days before: ' + j.p2 + ' on ' + j.p3 + ' with ' + j.p4 + '; asked them to reply YES to confirm or CHANGE to pick another time]';
    case 'tips': return '[Noor sent a welcome message for their first visit on ' + j.p2 + ': arrive 10 minutes early, bring the insurance card, free parking]';
    case 'followup': return '[Noor sent an automatic follow-up asking if they still want to book their ' + j.p2 + ', with Book now and Not now buttons]';
    case 'review': return '[Noor sent an automatic thank-you after the visit asking for a Google review; if anything was not right they can reply and the manager will contact them]';
    case 'feedback': return '[Noor sent an automatic message asking them to rate their visit with ' + j.p2 + ' from 1 (poor) to 5 (excellent)]';
    case 'missed': return '[Noor sent an automatic message: they missed their ' + j.p2 + ' appointment today; asked if they would like a new time]';
    case 'aftercare': return '[Noor sent an aftercare check-in asking how they feel after their ' + j.p2 + '. If they report severe pain, swelling or bleeding that will not stop, tell them to call the clinic right away and alert the staff]';
    case 'recall': return '[Noor sent an automatic 6-month check-up and cleaning reminder; asked them to reply with a day that suits them]';
    case 'winback': return '[Noor sent a win-back message asking if they would like to book a check-up; they can reply STOP to opt out]';
    default: return '[Noor sent an automatic message]';
  }
}
out.forEach(function (o) { o.json.history_text = hist(o.json); if (!o.json.log_kind) { o.json.log_kind = o.json.action; o.json.log_ref = String(r0(o.json)); } });
function r0(j) { return j.reminder_2h_sent || j.reminder_24h_sent || j.review_requested || ''; }
return out;

// Reminders (24h and 2h) and review requests for family bookings (Family Bookings tab).
// A family booking whose calendar event was deleted is marked cancelled instead of reminded.
const Z = 'Asia/Dubai';
const HOUR = 60 * 60 * 1000;
const now = DateTime.now().setZone(Z);
const lang = {};
$('Read Patients (Family)').all().forEach(function (i) { const r = i.json || {}; if (r.phone) lang[String(r.phone).replace(/\D/g, '')] = String(r.language || '').toLowerCase().startsWith('ar') ? 'ar' : 'en'; });
const live = {};
$('Family Events').all().forEach(function (i) { const e = i.json || {}; if (e.id && e.status !== 'cancelled') live[e.id] = true; });
const out = [];
for (const it of $('Read Family Bookings').all()) {
  const r = it.json || {};
  if (!r.key || !r.phone || !r.appointment_start) continue;
  if (String(r.status || '').toLowerCase() !== 'booked') continue;
  const phone = String(r.phone).replace(/\D/g, '');
  if (/^000000000000/.test(phone)) continue;
  const start = DateTime.fromFormat(String(r.appointment_start), 'yyyy-MM-dd HH:mm', { zone: Z });
  if (!start.isValid) continue;
  const ms = start.toMillis() - now.toMillis();
  const l = lang[phone] || 'en';
  const first = String(r.name || '').trim().split(' ')[0] || (l === 'ar' ? 'عزيزنا' : 'there');
  const service = String(r.service || (l === 'ar' ? 'الأسنان' : 'dental'));
  const key = String(r.appointment_start);
  const local = start.reconfigure({ locale: l, numberingSystem: 'latn' });
  const dateText = local.toFormat('cccc d LLLL');
  const timeText = l === 'ar' ? start.toFormat('h:mm') + (start.hour < 12 ? ' صباحاً' : ' مساءً') : start.toFormat('h:mm a');
  const base = { key: String(r.key), phone: phone, status: String(r.status || 'booked'), reminder_24h_sent: String(r.reminder_24h_sent || ''), reminder_2h_sent: String(r.reminder_2h_sent || ''), review_requested: String(r.review_requested || '') };
  if (ms > 0 && ms <= 48 * HOUR && !live[r.key]) { out.push({ json: Object.assign({}, base, { status: 'cancelled', action: 'none' }) }); continue; }
  if (ms > 0 && ms <= 2 * HOUR && base.reminder_2h_sent !== key) {
    out.push({ json: Object.assign({}, base, { reminder_2h_sent: key, reminder_24h_sent: key, action: 'reminder', template: 'appointment_reminder|' + l, p1: first, p2: service, p3: dateText, p4: timeText }) });
    continue;
  }
  if (ms > 2 * HOUR && ms <= 24 * HOUR && base.reminder_24h_sent !== key) {
    out.push({ json: Object.assign({}, base, { reminder_24h_sent: key, action: 'reminder', template: 'appointment_reminder|' + l, p1: first, p2: service, p3: dateText, p4: timeText }) });
    continue;
  }
  const reviewAt = start.toMillis() + 90 * 60 * 1000;
  if (now.toMillis() >= reviewAt && now.toMillis() - reviewAt < 48 * HOUR && base.review_requested !== key) {
    out.push({ json: Object.assign({}, base, { status: 'completed', review_requested: key, action: 'review', template: 'review_request|' + l, p1: first }) });
  }
}
return out;

// Finds appointments cancelled or moved since the last hourly check and offers the freed time
// to patients on the waitlist (slot_available template). Switch: slot_offers.
const Z = 'Asia/Dubai';
const now = DateTime.now().setZone(Z);
const on = {};
try { $('Get Switches').all().forEach(function (i) { const r = i.json || {}; if (r.feature) on[String(r.feature).trim()] = String(r.enabled).trim().toUpperCase() === 'TRUE'; }); } catch (e) { /* off */ }
const events = $('Upcoming Events').all().map(function (i) { return i.json || {}; }).filter(function (e) { return e.id && e.start && e.start.dateTime && e.status !== 'cancelled'; });
const current = {};
events.forEach(function (e) { current[e.id] = DateTime.fromISO(e.start.dateTime, { zone: Z }).toMillis(); });
const snap = $('Get Slot Snapshot').all().map(function (i) { return i.json || {}; }).filter(function (r) { return r.event_id; });
const control = function (ok) { return [{ json: { action: 'snapshot', ok: ok } }]; };
if (!events.length && snap.length >= 3) return control(false); // calendar read probably failed: change nothing
if (!on.slot_offers || !snap.length) return control(true);
if (now.hour < 9 || now.hour >= 20) return control(false); // offer in the morning instead
const freed = [];
snap.forEach(function (r) {
  const s = DateTime.fromISO(String(r.start), { zone: Z });
  if (!s.isValid) return;
  if (current[r.event_id] === s.toMillis()) return; // still booked at the same time
  if (s < now.plus({ hours: 3 }) || s > now.plus({ days: 14 })) return;
  freed.push({ start: s, summary: String(r.summary || '') });
});
if (!freed.length) return control(true);
const lang = {};
const names = {};
try { $('Read Patients').all().forEach(function (i) { const r = i.json || {}; const p = String(r.phone || '').replace(/\D/g, ''); if (!p) return; lang[p] = String(r.language || '').toLowerCase().startsWith('ar') ? 'ar' : 'en'; names[p] = String(r.name || '').trim().split(' ')[0]; }); } catch (e) { /* defaults */ }
const waiting = $('Read Requests').all().map(function (i) { return i.json || {}; }).filter(function (r) {
  if (!r.key || !r.phone || !/wait/i.test(String(r.type || ''))) return false;
  const st = String(r.status || '').toLowerCase().trim();
  if (st && st !== 'open' && st !== 'new') return false;
  if (/^000000000000/.test(String(r.phone).replace(/\D/g, ''))) return false;
  const t = DateTime.fromFormat(String(r.time || ''), 'yyyy-MM-dd HH:mm', { zone: Z });
  return !(t.isValid && now.diff(t, 'days').days > 14);
}).sort(function (a, b) { return String(a.time || '').localeCompare(String(b.time || '')); });
const out = [];
const used = {};
freed.slice(0, 2).forEach(function (f) {
  let n = 0;
  waiting.forEach(function (w) {
    if (n >= 3 || used[w.key]) return;
    const p = String(w.phone).replace(/\D/g, '');
    const l = lang[p] || 'en';
    const when = l === 'ar'
      ? f.start.reconfigure({ locale: 'ar', numberingSystem: 'latn' }).toFormat('cccc d LLLL') + ' الساعة ' + f.start.toFormat('h:mm') + (f.start.hour < 12 ? ' صباحاً' : ' مساءً')
      : f.start.toFormat('cccc d LLLL') + ' at ' + f.start.toFormat('h:mm a');
    used[w.key] = 1;
    n++;
    out.push({ json: {
      action: 'slot', key: String(w.key), phone: p, template: 'slot_available|' + l,
      p1: names[p] || (l === 'ar' ? 'عزيزنا' : 'there'), p2: l === 'ar' ? 'أسنان' : 'dental', p3: when,
      note: 'Offered the freed slot ' + f.start.toFormat('yyyy-MM-dd HH:mm') + ' (' + f.summary + ')',
      updated_at: now.toFormat('yyyy-MM-dd HH:mm'),
      history_text: '[Noor sent an automatic waitlist message: a slot opened on ' + f.start.toFormat('cccc d LLLL') + ' at ' + f.start.toFormat('h:mm a') + ' (Dubai time); asked them to reply YES to take it. If they say yes, check it is still free with find_free_slots and book it]'
    } });
  });
});
return out.concat(control(true));

// The calendar as it is now, so the next hourly run can spot cancelled or moved appointments.
return $('Upcoming Events').all().map(function (i) { return i.json || {}; })
  .filter(function (e) { return e.id && e.start && e.start.dateTime && e.status !== 'cancelled'; })
  .map(function (e) { return { json: { event_id: String(e.id), start: String(e.start.dateTime), summary: String(e.summary || '').slice(0, 200) } }; });
